"""
    Calculate the factorial of a positive integer
    https://en.wikipedia.org/wiki/Factorial

    >>> import math
    >>> all(factorial(i) == math.factorial(i) for i in range(20))
    True
    >>> factorial(0.1)
    Traceback (most recent call last):
        ...
    ValueError: factorial() only accepts integral values
    >>> factorial(-1)
    Traceback (most recent call last):
        ...
    ValueError: factorial() not defined for negative values
    """
def factorial(n: int) -> int {
    if not isinstance(n, int) {
        raise ValueError("factorial() only accepts integral values");
    }
    if (n < 0) {
        raise ValueError("factorial() not defined for negative values");
    }
    return 1 if ((n == 0) or (n == 1)) else (n * factorial((n - 1)));
}

"""
    Returns `True` if the point of `point_x`, `point_y` is inside the area
    described, inclusive of `area_left` and `area_top`.

    >>> isInside(0, 0, 0, 0, 10, 10)
    True
    >>> isInside(10, 0, 0, 0, 10, 10)
    False
    """
def isInside(
    point_x: Any,
    point_y: Any,
    area_left: Any,
    area_top: Any,
    area_width: Any,
    area_height: Any
) -> object {
    return (
        (area_left <= point_x < (area_left + area_width))
        and (area_top <= point_y < (area_top + area_height))
    );
}

