    """
def trapezoidal(f: Any, x_min: Any, x_max: Any, n: Any = 1000) -> float {
    h = (x_max - x_min) / n;
    jum = 0.5 * f(x_min);
    for i in range(1, n) {
        xi = x_min + (h * i);
        jum = jum + f(xi);
    }
    jum = jum + (0.5 * f(x_max));
    hasil = jum * h;
    return hasil;
}

